<template><div class="absolute inset-0"><transition-group name="fade" tag="div"><div v-for="(img,i) in images" :key="`slide-${i}`" v-if="currentIndex===i" class="absolute inset-0 bg-cover bg-center" :style="{ backgroundImage:`url(${img})` }"><div class="absolute inset-0 bg-gradient-to-b from-neutral-950/40 via-neutral-950/70 to-neutral-950"></div></div></transition-group></div></template><script setup>import { ref,onMounted,onBeforeUnmount } from 'vue';import hero1 from '../assets/hero1.png';import hero2 from '../assets/hero2.png';import hero3 from '../assets/hero3.png';const images=[hero1,hero2,hero3];const currentIndex=ref(0);let timer;onMounted(()=>{timer=setInterval(()=>{currentIndex.value=(currentIndex.value+1)%images.length;},5000);});onBeforeUnmount(()=>clearInterval(timer));</script><style scoped>.fade-enter-active,.fade-leave-active{transition:opacity 1s ease}.fade-enter-from,.fade-leave-to{opacity:0}</style>